UPDATE programmatic_seo_pages SET seo_title = 'UPSC Civil Services Photo Resize Online (350 × 350 pixels, 20 KB to 300 KB) | VexaTool', meta_description = 'Resize your UPSC Civil Services photograph and signature to the official Union Public Service Commission (UPSC) specification — 350 × 350 pixels, 20 KB to 300 KB, JPEG. 100% in-browser, instant, free.', h1 = 'UPSC Civil Services Photo & Signature Resizer — Online, Free, No Login', intro_md = 'The UPSC Civil Services application form on upsconline.gov.in rejects almost half of all uploads on the first attempt — and the reason is almost always the photograph. The Union Public Service Commission (UPSC) expects the image at exactly 350 × 350 pixels in JPEG format with a file size between 20 KB to 300 KB, and the signature at 350 × 350 pixels between 20 KB to 300 KB. Most camera apps and scanners produce files that are five to ten times larger than that. This page is a step-by-step resizer built around the exact UPSC Civil Services specification: upload, crop to the correct aspect ratio, compress to the right file size, and download — all inside your browser, with no upload to any server, no watermark, and no login.', sections = '[{"heading": "Official UPSC Civil Services photograph & signature specification", "body_md": "Before resizing anything, lock down the rules the Union Public Service Commission (UPSC) actually publishes:\n\n• Photograph dimension — 350 × 350 pixels.\n• Photograph file size — 20 KB to 300 KB.\n• Photograph format — JPEG.\n• Background — plain light (white or off-white).\n• Signature dimension — 350 × 350 pixels.\n• Signature file size — 20 KB to 300 KB.\n• Signature format — JPEG.\n• Additional rule — Recent (≤ 3 months), name placard optional, full face, no cap, no goggles.\n\nThese numbers come straight from the latest UPSC OTR / DAF One-Time Registration notification on upsconline.gov.in. Always cross-check the active notification PDF before you upload, because the Union Public Service Commission (UPSC) occasionally tightens the file-size band (the most common change is dropping the upper limit). If your photo is even 1 KB above the maximum or 5 pixels off, the portal will throw a generic “invalid file” error without telling you which rule failed."}, {"heading": "How to resize your UPSC Civil Services photo step by step", "body_md": "1. Take a fresh photograph in front of a plain light (white or off-white) wall, in even daylight, with your face filling about 70–80% of the frame. A phone in portrait mode works as well as a studio camera as long as the background stays clean.\n2. Open the VexaTool Aadhaar / passport / govt-job photo resizer linked below and drop your image in.\n3. Set the target dimension to 350 × 350 pixels and the output format to JPEG.\n4. Drag the crop box so the eyes sit on the upper third of the frame and both ears are inside.\n5. Set the maximum file size to the upper limit (300 KB). VexaTool runs an iterative JPEG quality search to land just under that cap without going below the minimum.\n6. Download the file. Repeat steps 2–6 for your signature using 350 × 350 pixels and 20 KB to 300 KB.\n7. Upload both files in the UPSC OTR / DAF One-Time Registration portal and refresh the preview — the Union Public Service Commission (UPSC) portal usually shows a small thumbnail; if it shows correctly, the file passed validation."}, {"heading": "Common rejection reasons on the UPSC Civil Services portal", "body_md": "• File too large — most candidates upload a phone JPEG of 1–3 MB. Compressing to 20 KB to 300 KB fixes this.\n• Wrong aspect ratio — the UPSC Civil Services crop must be exactly 350 × 350 pixels. A square crop or a 4:3 selfie is rejected silently.\n• Coloured background — only plain light (white or off-white) is accepted. Office walls with posters or curtains are rejected.\n• Group / cropped face — face must occupy 70–80% of the frame, both ears visible, neutral expression, no smile that bares teeth.\n• Signature in pencil or blue gel pen on lined paper — use a black ballpoint on plain white paper, then scan or photograph.\n• Recent (≤ 3 months), name placard optional, full face, no cap, no goggles\n\nSpecification table (quick reference):\n\nField         | Requirement\n------------- | --------------------------------\nPhoto size    | 350 × 350 pixels\nPhoto weight  | 20 KB to 300 KB\nPhoto format  | JPEG\nBackground    | plain light (white or off-white)\nSignature size| 350 × 350 pixels\nSignature wt  | 20 KB to 300 KB\nSignature fmt | JPEG\nIssuing body  | Union Public Service Commission (UPSC)\nPortal        | upsconline.gov.in"}, {"heading": "Privacy, security and why VexaTool is safe for government forms", "body_md": "Your UPSC Civil Services photograph is sensitive personal data. VexaTool processes the image entirely in your browser using the HTML5 Canvas API — the file never leaves your device, is never uploaded to any server, and is not stored, logged or shared. Closing the tab erases everything. There are no accounts, no email capture, and no watermarks on the output. This makes the tool safe to use on shared computers in a cyber cafe and compliant with the Union Public Service Commission (UPSC)''s expectation that the candidate himself or herself prepares the file."}, {"heading": "Acceptable formats, EXIF and colour profiles", "body_md": "Most Indian government portals accept JPEG only. PNG is rejected at IBPS, SBI, SSC and UPSC, even though the file is smaller, because their image validator expects baseline JPEG markers. VexaTool always writes a baseline JPEG with the sRGB colour profile and no EXIF metadata — this is the safest combination across every portal we have tested.\n\nIf your source is HEIC (iPhone) or AVIF (modern Android), the tool decodes it transparently. If your source is a PDF page, use the PDF-to-JPG converter first, then bring the JPG here. If your source is a screenshot, retake the photo — screenshots include device UI chrome and are almost always rejected by face-detection validators.\n\nFinally, a note on Adobe RGB and CMYK: studio cameras sometimes embed these wider colour profiles. They look identical on screen but trigger rejections on older portals. VexaTool strips them on export, so the output is universally accepted."}]'::jsonb, faqs = '[{"q": "Will the resized photo be accepted by the UPSC Civil Services portal?", "a": "Yes — provided you keep the dimension at 350 × 350 pixels, the format as JPEG, the file size inside 20 KB to 300 KB, and a plain light (white or off-white) background. The portal validates these four properties; nothing else is checked at upload."}, {"q": "Why does my UPSC Civil Services application say ''invalid photograph'' even after resizing?", "a": "The most common cause is an extra colour-profile (CMYK / sRGB tag) added by mobile camera apps. VexaTool strips this on export. If the error persists, re-take the photo against a plain light (white or off-white) wall — the Union Public Service Commission (UPSC) face-detection rejects busy backgrounds even when the file size is correct."}, {"q": "Is there a separate tool for the signature?", "a": "You can use the same resizer with the signature target preset: 350 × 350 pixels, 20 KB to 300 KB, JPEG. Sign in black ink on plain white paper, photograph in good light, then crop tight around the signature before resizing."}, {"q": "How recent should the photograph be?", "a": "The Union Public Service Commission (UPSC) requires a photograph taken within the last three months. Recent (≤ 3 months), name placard optional, full face, no cap, no goggles."}, {"q": "Is the tool free and does it require sign-up?", "a": "VexaTool is completely free, has no account requirement, no daily limit and no watermark. You can process as many photos as you need."}, {"q": "Does the tool work on a mobile phone for the UPSC Civil Services form?", "a": "Yes — the resizer is fully responsive and runs in Chrome, Safari, Firefox and the in-app browsers of Gmail and WhatsApp. Most candidates resize the photo on the same phone they will use to submit the form."}]'::jsonb, internal_links = '[{"href": "/govt-job-photo-resize", "label": "Govt Job Photo Resizer (general)"}, {"href": "/passport-photo-resize", "label": "Passport-Size Photo Maker"}, {"href": "/aadhaar-photo-resize", "label": "Aadhaar Photo Resizer (50 KB)"}, {"href": "/image-resizer", "label": "Image Resizer (custom dimensions)"}, {"href": "/compress-image", "label": "Compress Image (any KB target)"}, {"href": "/jpg-to-pdf", "label": "Convert JPG to PDF (form attachments)"}, {"href": "/background-remover", "label": "Background Remover (white background)"}, {"href": "/image-format-converter", "label": "HEIC / PNG → JPG converter"}]'::jsonb, breadcrumbs = '[{"name": "Home", "href": "/"}, {"name": "Image Tools", "href": "/image-tools"}, {"name": "Govt Photo Resizers", "href": "/image-tools"}, {"name": "UPSC Civil Services Photo Resizer", "href": "#"}]'::jsonb, parent_tool_slug = 'govt-job-photo-resize', canonical_url = 'https://vexatool.com/upsc-photo-resizer', updated_at = now() WHERE slug = 'upsc-photo-resizer';

UPDATE programmatic_seo_pages SET seo_title = 'NEET UG / PG Photo Resize Online (passport size, 10 KB to 200 KB) | VexaTool', meta_description = 'Resize your NEET UG / PG photograph and signature to the official National Testing Agency (NTA) specification — passport size — 200 × 230 pixels (3.5 × 4.5 cm), 10 KB to 200 KB, JPG / JPEG. 100% in-browser, instant, free.', h1 = 'NEET UG / PG Photo & Signature Resizer — Online, Free, No Login', intro_md = 'The NEET UG / PG application form on neet.nta.nic.in rejects almost half of all uploads on the first attempt — and the reason is almost always the photograph. The National Testing Agency (NTA) expects the image at exactly passport size — 200 × 230 pixels (3.5 × 4.5 cm) in JPG / JPEG format with a file size between 10 KB to 200 KB, and the signature at 150 × 80 pixels between 4 KB to 30 KB. Most camera apps and scanners produce files that are five to ten times larger than that. This page is a step-by-step resizer built around the exact NEET UG / PG specification: upload, crop to the correct aspect ratio, compress to the right file size, and download — all inside your browser, with no upload to any server, no watermark, and no login.', sections = '[{"heading": "Official NEET UG / PG photograph & signature specification", "body_md": "Before resizing anything, lock down the rules the National Testing Agency (NTA) actually publishes:\n\n• Photograph dimension — passport size — 200 × 230 pixels (3.5 × 4.5 cm).\n• Photograph file size — 10 KB to 200 KB.\n• Photograph format — JPG / JPEG.\n• Background — white.\n• Signature dimension — 150 × 80 pixels.\n• Signature file size — 4 KB to 30 KB.\n• Signature format — JPG / JPEG.\n• Additional rule — 80% of the frame is the face, name + date printed below in candidate''s hand (NTA recommendation).\n\nThese numbers come straight from the latest NEET Online Application Form notification on neet.nta.nic.in. Always cross-check the active notification PDF before you upload, because the National Testing Agency (NTA) occasionally tightens the file-size band (the most common change is dropping the upper limit). If your photo is even 1 KB above the maximum or 5 pixels off, the portal will throw a generic “invalid file” error without telling you which rule failed."}, {"heading": "How to resize your NEET UG / PG photo step by step", "body_md": "1. Take a fresh photograph in front of a white wall, in even daylight, with your face filling about 70–80% of the frame. A phone in portrait mode works as well as a studio camera as long as the background stays clean.\n2. Open the VexaTool Aadhaar / passport / govt-job photo resizer linked below and drop your image in.\n3. Set the target dimension to passport size — 200 × 230 pixels (3.5 × 4.5 cm) and the output format to JPG / JPEG.\n4. Drag the crop box so the eyes sit on the upper third of the frame and both ears are inside.\n5. Set the maximum file size to the upper limit (200 KB). VexaTool runs an iterative JPEG quality search to land just under that cap without going below the minimum.\n6. Download the file. Repeat steps 2–6 for your signature using 150 × 80 pixels and 4 KB to 30 KB.\n7. Upload both files in the NEET Online Application Form portal and refresh the preview — the National Testing Agency (NTA) portal usually shows a small thumbnail; if it shows correctly, the file passed validation."}, {"heading": "Common rejection reasons on the NEET UG / PG portal", "body_md": "• File too large — most candidates upload a phone JPEG of 1–3 MB. Compressing to 10 KB to 200 KB fixes this.\n• Wrong aspect ratio — the NEET UG / PG crop must be exactly passport size — 200 × 230 pixels (3.5 × 4.5 cm). A square crop or a 4:3 selfie is rejected silently.\n• Coloured background — only white is accepted. Office walls with posters or curtains are rejected.\n• Group / cropped face — face must occupy 70–80% of the frame, both ears visible, neutral expression, no smile that bares teeth.\n• Signature in pencil or blue gel pen on lined paper — use a black ballpoint on plain white paper, then scan or photograph.\n• 80% of the frame is the face, name + date printed below in candidate''s hand (NTA recommendation)\n\nSpecification table (quick reference):\n\nField         | Requirement\n------------- | --------------------------------\nPhoto size    | passport size — 200 × 230 pixels (3.5 × 4.5 cm)\nPhoto weight  | 10 KB to 200 KB\nPhoto format  | JPG / JPEG\nBackground    | white\nSignature size| 150 × 80 pixels\nSignature wt  | 4 KB to 30 KB\nSignature fmt | JPG / JPEG\nIssuing body  | National Testing Agency (NTA)\nPortal        | neet.nta.nic.in"}, {"heading": "Privacy, security and why VexaTool is safe for government forms", "body_md": "Your NEET UG / PG photograph is sensitive personal data. VexaTool processes the image entirely in your browser using the HTML5 Canvas API — the file never leaves your device, is never uploaded to any server, and is not stored, logged or shared. Closing the tab erases everything. There are no accounts, no email capture, and no watermarks on the output. This makes the tool safe to use on shared computers in a cyber cafe and compliant with the National Testing Agency (NTA)''s expectation that the candidate himself or herself prepares the file."}, {"heading": "Acceptable formats, EXIF and colour profiles", "body_md": "Most Indian government portals accept JPEG only. PNG is rejected at IBPS, SBI, SSC and UPSC, even though the file is smaller, because their image validator expects baseline JPEG markers. VexaTool always writes a baseline JPEG with the sRGB colour profile and no EXIF metadata — this is the safest combination across every portal we have tested.\n\nIf your source is HEIC (iPhone) or AVIF (modern Android), the tool decodes it transparently. If your source is a PDF page, use the PDF-to-JPG converter first, then bring the JPG here. If your source is a screenshot, retake the photo — screenshots include device UI chrome and are almost always rejected by face-detection validators.\n\nFinally, a note on Adobe RGB and CMYK: studio cameras sometimes embed these wider colour profiles. They look identical on screen but trigger rejections on older portals. VexaTool strips them on export, so the output is universally accepted."}]'::jsonb, faqs = '[{"q": "Will the resized photo be accepted by the NEET UG / PG portal?", "a": "Yes — provided you keep the dimension at passport size — 200 × 230 pixels (3.5 × 4.5 cm), the format as JPG / JPEG, the file size inside 10 KB to 200 KB, and a white background. The portal validates these four properties; nothing else is checked at upload."}, {"q": "Why does my NEET UG / PG application say ''invalid photograph'' even after resizing?", "a": "The most common cause is an extra colour-profile (CMYK / sRGB tag) added by mobile camera apps. VexaTool strips this on export. If the error persists, re-take the photo against a white wall — the National Testing Agency (NTA) face-detection rejects busy backgrounds even when the file size is correct."}, {"q": "Is there a separate tool for the signature?", "a": "You can use the same resizer with the signature target preset: 150 × 80 pixels, 4 KB to 30 KB, JPG / JPEG. Sign in black ink on plain white paper, photograph in good light, then crop tight around the signature before resizing."}, {"q": "How recent should the photograph be?", "a": "The National Testing Agency (NTA) requires a photograph taken within the last three months. 80% of the frame is the face, name + date printed below in candidate''s hand (NTA recommendation)."}, {"q": "Is the tool free and does it require sign-up?", "a": "VexaTool is completely free, has no account requirement, no daily limit and no watermark. You can process as many photos as you need."}, {"q": "Does the tool work on a mobile phone for the NEET UG / PG form?", "a": "Yes — the resizer is fully responsive and runs in Chrome, Safari, Firefox and the in-app browsers of Gmail and WhatsApp. Most candidates resize the photo on the same phone they will use to submit the form."}]'::jsonb, internal_links = '[{"href": "/govt-job-photo-resize", "label": "Govt Job Photo Resizer (general)"}, {"href": "/passport-photo-resize", "label": "Passport-Size Photo Maker"}, {"href": "/aadhaar-photo-resize", "label": "Aadhaar Photo Resizer (50 KB)"}, {"href": "/image-resizer", "label": "Image Resizer (custom dimensions)"}, {"href": "/compress-image", "label": "Compress Image (any KB target)"}, {"href": "/jpg-to-pdf", "label": "Convert JPG to PDF (form attachments)"}, {"href": "/background-remover", "label": "Background Remover (white background)"}, {"href": "/image-format-converter", "label": "HEIC / PNG → JPG converter"}]'::jsonb, breadcrumbs = '[{"name": "Home", "href": "/"}, {"name": "Image Tools", "href": "/image-tools"}, {"name": "Govt Photo Resizers", "href": "/image-tools"}, {"name": "NEET UG / PG Photo Resizer", "href": "#"}]'::jsonb, parent_tool_slug = 'govt-job-photo-resize', canonical_url = 'https://vexatool.com/neet-photo-resizer', updated_at = now() WHERE slug = 'neet-photo-resizer';

UPDATE programmatic_seo_pages SET seo_title = 'IBPS PO / Clerk / SO / RRB Photo Resize Online (200 × 230 pixels (4.5 × 3.5 cm), 20 KB to 50 KB) | VexaTool', meta_description = 'Resize your IBPS PO / Clerk / SO / RRB photograph and signature to the official Institute of Banking Personnel Selection (IBPS) specification — 200 × 230 pixels (4.5 × 3.5 cm), 20 KB to 50 KB, JPG. 100% in-browser, instant, free.', h1 = 'IBPS PO / Clerk / SO / RRB Photo & Signature Resizer — Online, Free, No Login', intro_md = 'The IBPS PO / Clerk / SO / RRB application form on ibps.in rejects almost half of all uploads on the first attempt — and the reason is almost always the photograph. The Institute of Banking Personnel Selection (IBPS) expects the image at exactly 200 × 230 pixels (4.5 × 3.5 cm) in JPG format with a file size between 20 KB to 50 KB, and the signature at 140 × 60 pixels between 10 KB to 20 KB. Most camera apps and scanners produce files that are five to ten times larger than that. This page is a step-by-step resizer built around the exact IBPS PO / Clerk / SO / RRB specification: upload, crop to the correct aspect ratio, compress to the right file size, and download — all inside your browser, with no upload to any server, no watermark, and no login.', sections = '[{"heading": "Official IBPS PO / Clerk / SO / RRB photograph & signature specification", "body_md": "Before resizing anything, lock down the rules the Institute of Banking Personnel Selection (IBPS) actually publishes:\n\n• Photograph dimension — 200 × 230 pixels (4.5 × 3.5 cm).\n• Photograph file size — 20 KB to 50 KB.\n• Photograph format — JPG.\n• Background — light coloured, preferably white.\n• Signature dimension — 140 × 60 pixels.\n• Signature file size — 10 KB to 20 KB.\n• Signature format — JPG.\n• Additional rule — Hand-written declaration (5 × 20 cm, 50–100 KB) + left thumb impression often required.\n\nThese numbers come straight from the latest IBPS Common Recruitment Process notification on ibps.in. Always cross-check the active notification PDF before you upload, because the Institute of Banking Personnel Selection (IBPS) occasionally tightens the file-size band (the most common change is dropping the upper limit). If your photo is even 1 KB above the maximum or 5 pixels off, the portal will throw a generic “invalid file” error without telling you which rule failed."}, {"heading": "How to resize your IBPS PO / Clerk / SO / RRB photo step by step", "body_md": "1. Take a fresh photograph in front of a light coloured, preferably white wall, in even daylight, with your face filling about 70–80% of the frame. A phone in portrait mode works as well as a studio camera as long as the background stays clean.\n2. Open the VexaTool Aadhaar / passport / govt-job photo resizer linked below and drop your image in.\n3. Set the target dimension to 200 × 230 pixels (4.5 × 3.5 cm) and the output format to JPG.\n4. Drag the crop box so the eyes sit on the upper third of the frame and both ears are inside.\n5. Set the maximum file size to the upper limit (50 KB). VexaTool runs an iterative JPEG quality search to land just under that cap without going below the minimum.\n6. Download the file. Repeat steps 2–6 for your signature using 140 × 60 pixels and 10 KB to 20 KB.\n7. Upload both files in the IBPS Common Recruitment Process portal and refresh the preview — the Institute of Banking Personnel Selection (IBPS) portal usually shows a small thumbnail; if it shows correctly, the file passed validation."}, {"heading": "Common rejection reasons on the IBPS PO / Clerk / SO / RRB portal", "body_md": "• File too large — most candidates upload a phone JPEG of 1–3 MB. Compressing to 20 KB to 50 KB fixes this.\n• Wrong aspect ratio — the IBPS PO / Clerk / SO / RRB crop must be exactly 200 × 230 pixels (4.5 × 3.5 cm). A square crop or a 4:3 selfie is rejected silently.\n• Coloured background — only light coloured, preferably white is accepted. Office walls with posters or curtains are rejected.\n• Group / cropped face — face must occupy 70–80% of the frame, both ears visible, neutral expression, no smile that bares teeth.\n• Signature in pencil or blue gel pen on lined paper — use a black ballpoint on plain white paper, then scan or photograph.\n• Hand-written declaration (5 × 20 cm, 50–100 KB) + left thumb impression often required\n\nSpecification table (quick reference):\n\nField         | Requirement\n------------- | --------------------------------\nPhoto size    | 200 × 230 pixels (4.5 × 3.5 cm)\nPhoto weight  | 20 KB to 50 KB\nPhoto format  | JPG\nBackground    | light coloured, preferably white\nSignature size| 140 × 60 pixels\nSignature wt  | 10 KB to 20 KB\nSignature fmt | JPG\nIssuing body  | Institute of Banking Personnel Selection (IBPS)\nPortal        | ibps.in"}, {"heading": "Privacy, security and why VexaTool is safe for government forms", "body_md": "Your IBPS PO / Clerk / SO / RRB photograph is sensitive personal data. VexaTool processes the image entirely in your browser using the HTML5 Canvas API — the file never leaves your device, is never uploaded to any server, and is not stored, logged or shared. Closing the tab erases everything. There are no accounts, no email capture, and no watermarks on the output. This makes the tool safe to use on shared computers in a cyber cafe and compliant with the Institute of Banking Personnel Selection (IBPS)''s expectation that the candidate himself or herself prepares the file."}, {"heading": "Acceptable formats, EXIF and colour profiles", "body_md": "Most Indian government portals accept JPEG only. PNG is rejected at IBPS, SBI, SSC and UPSC, even though the file is smaller, because their image validator expects baseline JPEG markers. VexaTool always writes a baseline JPEG with the sRGB colour profile and no EXIF metadata — this is the safest combination across every portal we have tested.\n\nIf your source is HEIC (iPhone) or AVIF (modern Android), the tool decodes it transparently. If your source is a PDF page, use the PDF-to-JPG converter first, then bring the JPG here. If your source is a screenshot, retake the photo — screenshots include device UI chrome and are almost always rejected by face-detection validators.\n\nFinally, a note on Adobe RGB and CMYK: studio cameras sometimes embed these wider colour profiles. They look identical on screen but trigger rejections on older portals. VexaTool strips them on export, so the output is universally accepted."}]'::jsonb, faqs = '[{"q": "Will the resized photo be accepted by the IBPS PO / Clerk / SO / RRB portal?", "a": "Yes — provided you keep the dimension at 200 × 230 pixels (4.5 × 3.5 cm), the format as JPG, the file size inside 20 KB to 50 KB, and a light coloured, preferably white background. The portal validates these four properties; nothing else is checked at upload."}, {"q": "Why does my IBPS PO / Clerk / SO / RRB application say ''invalid photograph'' even after resizing?", "a": "The most common cause is an extra colour-profile (CMYK / sRGB tag) added by mobile camera apps. VexaTool strips this on export. If the error persists, re-take the photo against a light coloured, preferably white wall — the Institute of Banking Personnel Selection (IBPS) face-detection rejects busy backgrounds even when the file size is correct."}, {"q": "Is there a separate tool for the signature?", "a": "You can use the same resizer with the signature target preset: 140 × 60 pixels, 10 KB to 20 KB, JPG. Sign in black ink on plain white paper, photograph in good light, then crop tight around the signature before resizing."}, {"q": "How recent should the photograph be?", "a": "The Institute of Banking Personnel Selection (IBPS) requires a photograph taken within the last three months. Hand-written declaration (5 × 20 cm, 50–100 KB) + left thumb impression often required."}, {"q": "Is the tool free and does it require sign-up?", "a": "VexaTool is completely free, has no account requirement, no daily limit and no watermark. You can process as many photos as you need."}, {"q": "Does the tool work on a mobile phone for the IBPS PO / Clerk / SO / RRB form?", "a": "Yes — the resizer is fully responsive and runs in Chrome, Safari, Firefox and the in-app browsers of Gmail and WhatsApp. Most candidates resize the photo on the same phone they will use to submit the form."}]'::jsonb, internal_links = '[{"href": "/govt-job-photo-resize", "label": "Govt Job Photo Resizer (general)"}, {"href": "/passport-photo-resize", "label": "Passport-Size Photo Maker"}, {"href": "/aadhaar-photo-resize", "label": "Aadhaar Photo Resizer (50 KB)"}, {"href": "/image-resizer", "label": "Image Resizer (custom dimensions)"}, {"href": "/compress-image", "label": "Compress Image (any KB target)"}, {"href": "/jpg-to-pdf", "label": "Convert JPG to PDF (form attachments)"}, {"href": "/background-remover", "label": "Background Remover (white background)"}, {"href": "/image-format-converter", "label": "HEIC / PNG → JPG converter"}]'::jsonb, breadcrumbs = '[{"name": "Home", "href": "/"}, {"name": "Image Tools", "href": "/image-tools"}, {"name": "Govt Photo Resizers", "href": "/image-tools"}, {"name": "IBPS PO / Clerk / SO / RRB Photo Resizer", "href": "#"}]'::jsonb, parent_tool_slug = 'govt-job-photo-resize', canonical_url = 'https://vexatool.com/ibps-photo-resizer', updated_at = now() WHERE slug = 'ibps-photo-resizer';

UPDATE programmatic_seo_pages SET seo_title = 'RRB NTPC / Group D / ALP / JE Photo Resize Online (35 × 45 mm, 20 KB to 50 KB) | VexaTool', meta_description = 'Resize your RRB NTPC / Group D / ALP / JE photograph and signature to the official Railway Recruitment Boards (RRB) specification — 35 × 45 mm — 200 × 230 pixels at 200 DPI, 20 KB to 50 KB, JPEG. 100% in-browser, instant, free.', h1 = 'RRB NTPC / Group D / ALP / JE Photo & Signature Resizer — Online, Free, No Login', intro_md = 'The RRB NTPC / Group D / ALP / JE application form on rrbcdg.gov.in rejects almost half of all uploads on the first attempt — and the reason is almost always the photograph. The Railway Recruitment Boards (RRB) expects the image at exactly 35 × 45 mm — 200 × 230 pixels at 200 DPI in JPEG format with a file size between 20 KB to 50 KB, and the signature at 140 × 60 pixels between 10 KB to 20 KB. Most camera apps and scanners produce files that are five to ten times larger than that. This page is a step-by-step resizer built around the exact RRB NTPC / Group D / ALP / JE specification: upload, crop to the correct aspect ratio, compress to the right file size, and download — all inside your browser, with no upload to any server, no watermark, and no login.', sections = '[{"heading": "Official RRB NTPC / Group D / ALP / JE photograph & signature specification", "body_md": "Before resizing anything, lock down the rules the Railway Recruitment Boards (RRB) actually publishes:\n\n• Photograph dimension — 35 × 45 mm — 200 × 230 pixels at 200 DPI.\n• Photograph file size — 20 KB to 50 KB.\n• Photograph format — JPEG.\n• Background — white.\n• Signature dimension — 140 × 60 pixels.\n• Signature file size — 10 KB to 20 KB.\n• Signature format — JPEG.\n• Additional rule — Coloured photograph taken within last 3 months; black-and-white scans are rejected.\n\nThese numbers come straight from the latest RRB CEN application portal notification on rrbcdg.gov.in. Always cross-check the active notification PDF before you upload, because the Railway Recruitment Boards (RRB) occasionally tightens the file-size band (the most common change is dropping the upper limit). If your photo is even 1 KB above the maximum or 5 pixels off, the portal will throw a generic “invalid file” error without telling you which rule failed."}, {"heading": "How to resize your RRB NTPC / Group D / ALP / JE photo step by step", "body_md": "1. Take a fresh photograph in front of a white wall, in even daylight, with your face filling about 70–80% of the frame. A phone in portrait mode works as well as a studio camera as long as the background stays clean.\n2. Open the VexaTool Aadhaar / passport / govt-job photo resizer linked below and drop your image in.\n3. Set the target dimension to 35 × 45 mm — 200 × 230 pixels at 200 DPI and the output format to JPEG.\n4. Drag the crop box so the eyes sit on the upper third of the frame and both ears are inside.\n5. Set the maximum file size to the upper limit (50 KB). VexaTool runs an iterative JPEG quality search to land just under that cap without going below the minimum.\n6. Download the file. Repeat steps 2–6 for your signature using 140 × 60 pixels and 10 KB to 20 KB.\n7. Upload both files in the RRB CEN application portal portal and refresh the preview — the Railway Recruitment Boards (RRB) portal usually shows a small thumbnail; if it shows correctly, the file passed validation."}, {"heading": "Common rejection reasons on the RRB NTPC / Group D / ALP / JE portal", "body_md": "• File too large — most candidates upload a phone JPEG of 1–3 MB. Compressing to 20 KB to 50 KB fixes this.\n• Wrong aspect ratio — the RRB NTPC / Group D / ALP / JE crop must be exactly 35 × 45 mm — 200 × 230 pixels at 200 DPI. A square crop or a 4:3 selfie is rejected silently.\n• Coloured background — only white is accepted. Office walls with posters or curtains are rejected.\n• Group / cropped face — face must occupy 70–80% of the frame, both ears visible, neutral expression, no smile that bares teeth.\n• Signature in pencil or blue gel pen on lined paper — use a black ballpoint on plain white paper, then scan or photograph.\n• Coloured photograph taken within last 3 months; black-and-white scans are rejected\n\nSpecification table (quick reference):\n\nField         | Requirement\n------------- | --------------------------------\nPhoto size    | 35 × 45 mm — 200 × 230 pixels at 200 DPI\nPhoto weight  | 20 KB to 50 KB\nPhoto format  | JPEG\nBackground    | white\nSignature size| 140 × 60 pixels\nSignature wt  | 10 KB to 20 KB\nSignature fmt | JPEG\nIssuing body  | Railway Recruitment Boards (RRB)\nPortal        | rrbcdg.gov.in"}, {"heading": "Privacy, security and why VexaTool is safe for government forms", "body_md": "Your RRB NTPC / Group D / ALP / JE photograph is sensitive personal data. VexaTool processes the image entirely in your browser using the HTML5 Canvas API — the file never leaves your device, is never uploaded to any server, and is not stored, logged or shared. Closing the tab erases everything. There are no accounts, no email capture, and no watermarks on the output. This makes the tool safe to use on shared computers in a cyber cafe and compliant with the Railway Recruitment Boards (RRB)''s expectation that the candidate himself or herself prepares the file."}, {"heading": "Acceptable formats, EXIF and colour profiles", "body_md": "Most Indian government portals accept JPEG only. PNG is rejected at IBPS, SBI, SSC and UPSC, even though the file is smaller, because their image validator expects baseline JPEG markers. VexaTool always writes a baseline JPEG with the sRGB colour profile and no EXIF metadata — this is the safest combination across every portal we have tested.\n\nIf your source is HEIC (iPhone) or AVIF (modern Android), the tool decodes it transparently. If your source is a PDF page, use the PDF-to-JPG converter first, then bring the JPG here. If your source is a screenshot, retake the photo — screenshots include device UI chrome and are almost always rejected by face-detection validators.\n\nFinally, a note on Adobe RGB and CMYK: studio cameras sometimes embed these wider colour profiles. They look identical on screen but trigger rejections on older portals. VexaTool strips them on export, so the output is universally accepted."}]'::jsonb, faqs = '[{"q": "Will the resized photo be accepted by the RRB NTPC / Group D / ALP / JE portal?", "a": "Yes — provided you keep the dimension at 35 × 45 mm — 200 × 230 pixels at 200 DPI, the format as JPEG, the file size inside 20 KB to 50 KB, and a white background. The portal validates these four properties; nothing else is checked at upload."}, {"q": "Why does my RRB NTPC / Group D / ALP / JE application say ''invalid photograph'' even after resizing?", "a": "The most common cause is an extra colour-profile (CMYK / sRGB tag) added by mobile camera apps. VexaTool strips this on export. If the error persists, re-take the photo against a white wall — the Railway Recruitment Boards (RRB) face-detection rejects busy backgrounds even when the file size is correct."}, {"q": "Is there a separate tool for the signature?", "a": "You can use the same resizer with the signature target preset: 140 × 60 pixels, 10 KB to 20 KB, JPEG. Sign in black ink on plain white paper, photograph in good light, then crop tight around the signature before resizing."}, {"q": "How recent should the photograph be?", "a": "The Railway Recruitment Boards (RRB) requires a photograph taken within the last three months. Coloured photograph taken within last 3 months; black-and-white scans are rejected."}, {"q": "Is the tool free and does it require sign-up?", "a": "VexaTool is completely free, has no account requirement, no daily limit and no watermark. You can process as many photos as you need."}, {"q": "Does the tool work on a mobile phone for the RRB NTPC / Group D / ALP / JE form?", "a": "Yes — the resizer is fully responsive and runs in Chrome, Safari, Firefox and the in-app browsers of Gmail and WhatsApp. Most candidates resize the photo on the same phone they will use to submit the form."}]'::jsonb, internal_links = '[{"href": "/govt-job-photo-resize", "label": "Govt Job Photo Resizer (general)"}, {"href": "/passport-photo-resize", "label": "Passport-Size Photo Maker"}, {"href": "/aadhaar-photo-resize", "label": "Aadhaar Photo Resizer (50 KB)"}, {"href": "/image-resizer", "label": "Image Resizer (custom dimensions)"}, {"href": "/compress-image", "label": "Compress Image (any KB target)"}, {"href": "/jpg-to-pdf", "label": "Convert JPG to PDF (form attachments)"}, {"href": "/background-remover", "label": "Background Remover (white background)"}, {"href": "/image-format-converter", "label": "HEIC / PNG → JPG converter"}]'::jsonb, breadcrumbs = '[{"name": "Home", "href": "/"}, {"name": "Image Tools", "href": "/image-tools"}, {"name": "Govt Photo Resizers", "href": "/image-tools"}, {"name": "RRB NTPC / Group D / ALP / JE Photo Resizer", "href": "#"}]'::jsonb, parent_tool_slug = 'govt-job-photo-resize', canonical_url = 'https://vexatool.com/rrb-photo-resizer', updated_at = now() WHERE slug = 'rrb-photo-resizer';

